package dev.notecore.canvas.prototype

import kotlin.test.*

/** Same native image workload on ART and Kotlin/Native; no fixture generated by a platform. */
internal object BrushTileImageFixture {
    val frame = FrameToken(SceneId("image-page"), 1, 1, 1, 1, 1)
    val layer = LayerId("ink")
    val grid = BrushTileGridPoc(PointD(0.25, 8.0), 64, 32, pixelSize = 0.5, samplesPerAxis = 4)
    const val rgb = 0x336699
    fun catalog(kind: BrushKind = BrushKind.HIGHLIGHTER): ChunkedBrushPoc {
        val samples = StrokeSamples.copyOf(doubleArrayOf(4.0, 16.0, 28.0, 4.0), doubleArrayOf(10.0, 21.0, 11.0, 10.0),
            floatArrayOf(1f, 0.25f, 1f, 1f), longArrayOf(0, 1, 2, 3))
        val stroke = StrokeObject(ObjectId("native-image"), 1, layer, BrushSpec(kind, 1, 7.0, 0xcc336699.toInt()), samples)
        return (ChunkedBrushPoc.build(frame, stroke, segmentsPerChunk = 1) as ChunkedBrushBuild.Ready).catalog
    }
    fun reader(cache: BrushTileCachePoc, catalog: ChunkedBrushPoc, grid: BrushTileGridPoc = this.grid) =
        (cache.acquire(catalog, frame, layer, grid) as CachedBrushTileBuild.Ready).reader
}

class BrushTilePixelsPocTest {
    private val f = BrushTileImageFixture
    @Test fun rgbaPremultipliesOnceAndRemainsOwnedAfterReaderReturn() {
        val cache = BrushTileCachePoc(32768, 65536); val reader = f.reader(cache, f.catalog())
        val image = assertIs<BrushTilePixelBuild.Ready>(BrushTilePixelsPoc.build(reader, f.rgb)).pixels
        assertEquals(f.frame, image.frame); assertEquals(f.layer, image.ownerLayer); assertEquals(8192, image.logicalBytes)
        var full = 0; var partial = 0
        for (i in 0 until 2048) {
            val alpha = reader.alphaByte(i % 64, i / 64)
            if (alpha == 51) full++ else if (alpha in 1..50) partial++
            assertEquals(alpha, image.byteAt(i * 4 + 3))
            for ((channel, color) in listOf(0 to 51, 1 to 102, 2 to 153))
                assertEquals((color * alpha + 127) / 255, image.byteAt(i * 4 + channel))
        }
        assertTrue(full > 0 && partial > 0)
        cache.returnReader(reader); cache.close(); assertTrue(cache.isDrained)
        assertEquals(f.rgb, image.rgb); assertEquals(0, image.byteAt(3)) // Output owns its separate copy.
    }

    @Test fun pixelBudgetAndCancellationDoNotPublishPartialPayloadOrReturnReader() {
        val cache = BrushTileCachePoc(32768, 65536); val reader = f.reader(cache, f.catalog())
        assertEquals("pixel-budget", assertIs<BrushTilePixelBuild.Rejected>(BrushTilePixelsPoc.build(reader, f.rgb, maxBytes = 8191)).reason)
        assertIs<BrushTilePixelBuild.Rejected>(BrushTilePixelsPoc.build(reader, -1))
        assertIs<BrushTilePixelBuild.Cancelled>(BrushTilePixelsPoc.build(reader, f.rgb, cancelled = { true }))
        var checks = 0
        assertIs<BrushTilePixelBuild.Cancelled>(BrushTilePixelsPoc.build(reader, f.rgb, cancelled = { ++checks > 3 }))
        assertEquals(1, cache.outstandingReaders)
        assertIs<BrushTilePixelBuild.Ready>(BrushTilePixelsPoc.build(reader, f.rgb, maxBytes = 8192))
        cache.returnReader(reader); cache.close(); assertTrue(cache.isDrained)
    }

    @Test fun expandedGridIncludesTrueNeighborsAndKeepsWorldSubpixelLattice() {
        val cache = BrushTileCachePoc(65536, 131072); val c = f.catalog()
        val full = f.reader(cache, c, f.grid.withGutter(1)!!)
        for (side in 0..1) {
            val core = f.grid.copy(origin = PointD(0.25 + side * 16, 8.0), width = 32)
            val padded = f.reader(cache, c, core.withGutter(1)!!)
            for (y in 0 until padded.grid.height) for (x in 0 until padded.grid.width)
                assertEquals(full.coverageBits(x + side * 32, y), padded.coverageBits(x, y))
            cache.returnReader(padded)
        }
        cache.returnReader(full); cache.close(); assertTrue(cache.isDrained)
    }

    @Test fun gutterAdmissionDoesNotClampOrChangePixelSizeAndSampling() {
        assertEquals(f.grid, f.grid.withGutter(0))
        val expanded = f.grid.withGutter(1)!!
        assertEquals(PointD(-0.25, 7.5), expanded.origin); assertEquals(66, expanded.width); assertEquals(34, expanded.height)
        assertEquals(f.grid.pixelSize, expanded.pixelSize); assertEquals(4, expanded.samplesPerAxis)
        assertNull(f.grid.copy(width = 128).withGutter(1))
        assertNull(f.grid.copy(origin = PointD(-1e9, 0.0)).withGutter(1))
        assertFailsWith<IllegalArgumentException> { f.grid.withGutter(5) }
    }
}
